protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = graph.getGraphPathFactory().createGraphPath();

    if (tour.isEmpty()) {
        return path;
    }

    // Find the edge with the smallest endpoint to start the path
    E firstEdge = null;
    V startVertex = null;
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (startVertex == null || source.toString().compareTo(startVertex.toString()) < 0) {
            startVertex = source;
            firstEdge = edge;
        } else if (target.toString().compareTo(startVertex.toString()) < 0) {
            startVertex = target;
            firstEdge = edge;
        }
    }

    // Add the first edge to the path
    path.addFirst(firstEdge);

    // Determine the direction of the first edge from the start vertex
    V currentVertex = null;
    if (graph.getEdgeSource(firstEdge).equals(startVertex)) {
        currentVertex = graph.getEdgeTarget(firstEdge);
    } else {
        currentVertex = graph.getEdgeSource(firstEdge);
    }

    // Build the rest of the path
    while (!tour.isEmpty()) {
        E nextEdge = null;
        for (E edge : tour) {
            V source = graph.getEdgeSource(edge);
            V target = graph.getEdgeTarget(edge);
            if (source.equals(currentVertex) || target.equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            // No more edges can be added
            break;
        }

        tour.remove(nextEdge);
        path.addLast(nextEdge);

        // Update current vertex
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        currentVertex = source.equals(currentVertex) ? target : source;
    }

    return path;
}
