protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    Map<E, Integer> edgeIndex = new HashMap<>();
    int index = 0;
    for (E edge : tour) {
        edgeIndex.put(edge, index++);
    }

    Map<V, Set<V>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V source = edge.getSource();
        V target = edge.getTarget();
        adjacency.computeIfAbsent(source, k -> new HashSet<>()).add(target);
        adjacency.computeIfAbsent(target, k -> new HashSet<>()).add(source);
    }

    List<GraphNode<V>> result = new ArrayList<>();
    Map<V, Integer> nodeIndex = new HashMap<>();

    // Find a node with an edge to start the path
    V startNode = null;
    for (V node : graph.nodes().toArray(new V[0])) {
        if (adjacency.containsKey(node) && !adjacency.get(node).isEmpty()) {
            startNode = node;
            break;
        }
    }

    if (startNode == null) {
        return new GraphPath<>(graph, new ArrayList<>(), new ArrayList<>());
    }

    Deque<V> nodes = new ArrayDeque<>();
    Deque<E> edges = new ArrayDeque<>();

    V current = startNode;
    Map<V, Set<V>> visitedAdjacent = new HashMap<>();
    Map<V, E> visitedEdge = new HashMap<>();

    nodes.addFirst(current);
    visitedAdjacent.put(current, new HashSet<>());

    while (!nodes.isEmpty()) {
        V nextNode = null;
        E nextEdge = null;
        int nextIndex = -1;

        // Find the next edge to follow (if any)
        Set<V> adjacentNodes = adjacency.getOrDefault(current, Collections.emptySet());
        for (V v : adjacentNodes) {
            if (!visitedAdjacent.containsKey(current) || !visitedAdjacent.get(current).contains(v)) {
                // Check if there's an edge between current and v
                for (E e : tour) {
                    if ((e.getSource().equals(current) && e.getTarget().equals(v)) ||
                        (e.getSource().equals(v) && e.getTarget().equals(current))) {
                        nextNode = v;
                        nextEdge = e;
                        nextIndex = edgeIndex.get(e);
                        break;
                    }
                }
                if (nextNode != null) {
                    break;
                }
            }
        }

        if (nextNode != null) {
            // Mark the edge as visited
            if (!visitedAdjacent.containsKey(current)) {
                visitedAdjacent.put(current, new HashSet<>());
            }
            visitedAdjacent.get(current).add(nextNode);
            if (!visitedAdjacent.containsKey(nextNode)) {
                visitedAdjacent.put(nextNode, new HashSet<>());
            }
            visitedAdjacent.get(nextNode).add(current);
            visitedEdge.put(current, nextEdge);

            nodes.addFirst(nextNode);
            edges.addFirst(nextEdge);
            current = nextNode;
        } else {
            // Backtrack
            V prev = nodes.removeFirst();
            if (!edges.isEmpty()) {
                E prevEdge = edges.removeFirst();
                // Remove the visited mark for this edge
                if (visitedAdjacent.containsKey(prev)) {
                    visitedAdjacent.get(prev).remove(current);
                }
                if (visitedAdjacent.containsKey(current)) {
                    visitedAdjacent.get(current).remove(prev);
                }
                nodes.addLast(prev);
                current = prev;
            }
        }
    }

    List<GraphNode<V>> graphNodes = new ArrayList<>();
    List<GraphEdge<V, E>> graphEdges = new ArrayList<>();

    for (V node : nodes) {
        graphNodes.add(new DefaultGraphNode<>(node));
    }

    for (E edge : edges) {
        graphEdges.add(new DefaultGraphEdge<>(edge.getSource(), edge.getTarget(), edge));
    }

    return new SimpleGraphPath<>(graph, graphNodes, graphEdges);
}
