private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int len = input.length();
    while (i < len) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            if ((next >= '0' && next <= '9') || (next >= 'A' && next <= 'Z') || (next >= 'a' && next <= 'z') || next == '_' || next == '$') {
                sb.append(next);
                i += 2;
            } else {
                sb.append(c);
                i++;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

private String unescapeId(String input) {
    StringBuilder buf = new StringBuilder();
    int len = input.length();
    for (int idx = 0; idx < len; ++idx) {
        char cur = input.charAt(idx);
        if (cur == '\\' && idx + 1 < len) {
            char next = input.charAt(++idx);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    break;
                case 't':
                    buf.append('\t');
                    break;
                case 'r':
                    buf.append('\r');
                    break;
                case 'f':
                    buf.append('\f');
                    break;
                case 'b':
                    buf.append('\b');
                    break;
                case 'e':
                    buf.append(0x1b);
                    break;
                case 'u':
                    if (idx + 4 < len) {
                        buf.append((char) Integer.parseInt(input.substring(idx + 1, idx + 5), 16));
                        idx += 4;
                    } else {
                        buf.append('\\');
                        buf.append('u');
                    }
                    break;
                default:
                    buf.append(next);
                    break;
            }
        } else {
            buf.append(cur);
        }
    }
    return buf.toString();
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char next = input.charAt(i + 1);
            if (next == '\\' || next == '"' || next == '\'') {
                result.append(next);
                i++;
                // skip the character after the backslash
            } else {
                result.append(c);
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

