public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    long current = 1;
    for (ProfileSegment segment : profile.getSegments()) {
        if (segment.hasSnapshot()) {
            if (current <= segment.getStartSequenceNumber()) {
                ranges.add(new SequenceRange(String.valueOf(current), String.valueOf(segment.getStartSequenceNumber() - 1)));
            }
            ranges.add(new SequenceRange(segment.getStartSequenceNumberAsString(), segment.getEndSequenceNumberAsString()));
            current = segment.getEndSequenceNumber() + 1;
        }
    }
    if (current <= profile.getPeakWindowState()) {
        ranges.add(new SequenceRange(String.valueOf(current), String.valueOf(profile.getPeakWindowState())));
    }
    return ranges;
}
