private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
        List<Integer> suffixSums = new ArrayList<Integer>(bounds.size());
        Long sumOfAll = 0L;
        Long current = 0L;
        for (int i = bounds.size() - 1; i >= 0; i--) {
            current += bounds.get(i);
            suffixSums.add(0, current.intValue());
        }
        for (int i = 0; i < bounds.size(); i++) {
            sumOfAll += bounds.get(i);
        }
        return Pair.of(suffixSums, sumOfAll);
    }

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;
    for (int bound : bounds) {
        sum += bound;
    }
    for (int bound : bounds) {
        sum -= bound;
        suffixSumList.add((int) sum);
    }
    return new Pair<>(suffixSumList, sum);
}

