        int prevBound = -1;
        for (int i = 0; i < keys.size(); i++) {
            K key = keys.get(i);
            int bound = prevBound + 1;
            for (int j = prevBound + 1; j < i; j++) {
                if (keys.get(j).compareTo(key) < 0) {
                    bound = j + 1;
                }
            }
            bounds.add(bound);
            if (bound > prevBound) {
                prevBound = bound;
            }
        }
        return bounds;
    }
