List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> snapshots = readAllSnapshots(file);
	if (timeRanges == null || timeRanges.isEmpty()) {
		return snapshots;
	}
	List<ThreadSnapshot> results = new LinkedList<ThreadSnapshot>();
	for (ThreadSnapshot snapshot : snapshots) {
		for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
			if (timeRange.contains(snapshot.getTime())) {
				results.add(snapshot);
				break;
			}
		}
	}
	return results;
}
