public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        List<ThreadSnapshot> snapshots = new ArrayList<>();
        while ((line = reader.readLine()) != null) {
            // Assuming a simple format, e.g., "timestamp:thread_name:java_stack_trace"
            String[] parts = line.split(":");
            if (parts.length >= 3) {
                long timestamp = Long.parseLong(parts[0]);
                String threadName = parts[1];
                String stackTrace = String.join(":", Arrays.copyOfRange(parts, 2, parts.length));

                boolean inRange = timeRanges.stream().anyMatch(range -> range.isInRange(timestamp) || range.getName().equals(threadName));
                if (inRange) {
                    ThreadSnapshot snapshot = new ThreadSnapshot(threadName, stackTrace, timestamp);
                    snapshots.add(snapshot);
                }
            }
        }
        return snapshots;
    }
}
